// RFC822 converter for us. However, in some cases, we might want to run it
// ourselves, e.g. when displaying an attachment (inline, PDF, etc.).
//
// In the case of displaying an attachment, we need to run our own converter
// first (before any that `nsDocShell` deems appropriate), because when e.g.
// displaying a PDF, the message/rfc822->application/pdf conversion and the
// application/pdf->text/html conversion are each handled by separate stream
// converters (the former by our own, and the latter by PDF.js).
//
// Other cases (with `convert=true` in the query) likely originate from using
// `ExchangeService::StreamMessage`. In theory we could run the stream
// converter there directly, but we want to centralise calls to the stream
// converter service as much as possible for maintainability.
bool convert = false;
if (spec.Find("part=") != kNotFound ||
    spec.Find("convert=true") != kNotFound) {
  convert = true;
}

RefPtr<ExchangeMessageChannel> channel =
    new ExchangeMessageChannel(aURI, convert);
MOZ_TRY(channel->SetLoadInfo(aLoadinfo));

if (MsgPartUrlNeedsAttachmentDisposition(aURI)) {
  MOZ_TRY(channel->SetContentDisposition(nsIChannel::DISPOSITION_ATTACHMENT));
}

nsresult ExchangeMessageChannel::StartMessageReadFromStore(
    nsIStreamListener* streamListener) {
  nsresult rv = AsyncReadMessageFromStore(mHdr, streamListener, mConvert, this,
                                          getter_AddRefs(mReadRequest));
  NS_ENSURE_SUCCESS(rv, rv);

// Set up a stream converter if required.
nsCOMPtr<nsIStreamListener> consumerListener = listenerWrapper;
if (convertData) {
  nsCOMPtr<nsIStreamConverterService> streamConverterService =
      mozilla::components::StreamConverter::Service();

  nsCOMPtr<nsIStreamListener> convertedListener;
  nsresult rv = streamConverterService->AsyncConvertData(
      MESSAGE_RFC822, ANY_WILDCARD, listenerWrapper, srcChannel,
      getter_AddRefs(consumerListener));
  NS_ENSURE_SUCCESS(rv, rv);
}

MOZ_TRY(pump->AsyncRead(consumerListener));
